/*
 * TEST DOUBLE of the video SDK, for the end-to-end tests of the call page (ADR 0123 steps 4c, 5a and 5b).
 *
 * This is not the SDK and contains nothing of it. It offers the surface the page's script uses and
 * nothing else, and what it does is chosen by the test before the page loads:
 *
 *   window.__sdkPlan = {
 *     failures: 0,   // the first N registrations are refused, then it works
 *     hang: 0,       // the first N registrations never answer (the page's own timeout ends them)
 *     always: false, // every registration is refused
 *     delay: 0,      // milliseconds a working registration takes
 *     authFailures: 0, // the first N registrations are refused as not authorised (401)
 *     unpublishFails: false, // taking a stream out of the meeting is refused
 *     joinDelay: 0, // milliseconds joining the meeting takes (the page is still connecting)
 *     hangUnpublish: false, // taking a stream out of the meeting never answers (the page's own time limit ends it)
 *     slowUnpublish: 0, // milliseconds taking a stream out of the meeting takes
 *     publishFails: false, // sending a new stream into the meeting is refused
 *     authFailAt: "",  // "create" or "join": the first such step is refused as not authorised (401)
 *     slowLeave: 0,  // milliseconds leaving the meeting takes
 *     late: 0,       // the first registration answers only after this many milliseconds
 *     mediaFailures: 0, // the first N attempts to add the media are refused (after a join)
 *     lobby: false,  // joining ends in the lobby; the test lets the participant in: __sdk.admit()
 *     remote: true,  // pictures and sound of the other side after the media is added
 *     deviceFails: [], // device ids that cannot be taken (the browser refuses them): a choice of one fails
 *     captions: false, // the meeting offers captions (isTranscriptionSupported)
 *     captionsFail: false, // starting captions is refused
 *     canShare: true, // the meeting lets the participant share a screen (inMeetingActions)
 *     shareSendFails: false, // sending the screen into the meeting is refused
 *     holdPublish: false, // sending the screen stays under way until the test calls __sdk.releasePublish()
 *   };
 *
 * and read afterwards in `window.__sdk`: the calls made, in order (`calls`), the options of every
 * `init` (`inits`, with the token the page gave), the meeting's link (`link`), the devices asked for
 * (`devices`), `admit()`, `end()` (the staff member ends the meeting), `remoteCamera(on)` (the
 * other side's camera goes off or on), `remoteAgain()` (the other side's sound is announced again),
 * `recording(on, payload)` (the meeting's recording starts or stops), `reconnection(step, payload)`
 * ("start", "success" or "fail": the connection is being restored, is back, or is lost for good; the
 * payload is what the event carries, which the page must never show), `left`. The events are
 * ones of the stand-in's own emitter, so the page's listeners are called as an engine would call them
 * (a made-up DOM event on a track would not reach them in Firefox). Publishing a stream records its
 * kind in `published` (a camera or microphone chosen in the call is sent that way, a screen as
 * `screenShare`); `publishFails` refuses it. Sharing and captions (step 5b): `remoteShare(on)` (the
 * staff member's screen starts or stops: a canvas stream), `stopLocalShare()` (the meeting ends the
 * participant's share), `rights(share, captions)` (what the meeting offers changes),
 * `caption({ finals: [{ id, text, own }], interim: [{ text, own }] })` (a caption event with two
 * speakers; the names the platform gives them are `Platform Self Name` and `Platform Person Name`,
 * which the page must never show), `captioning` (captions are running), `captionLanguage` and, in
 * `calls`, `updateLLMConnection`, `startTranscription`, `stopTranscription`, `setCaptionLanguage`
 * and `createDisplayStream`. The screen of the participant is whatever `navigator.mediaDevices.
 * getDisplayMedia` gives (the test stubs it); the double asks for it only when the page asks for a
 * display stream, so nothing is captured before a press.
 *
 * It lives in e2e/vendor/webex/ and is placed over the vendored file only by the end-to-end
 * stack (.github/actions/e2e-stack), together with a manifest whose checksum is this file's.
 * .dockerignore keeps e2e/ out of every image; tests/web/test_vendor_stand_in.py keeps it so.
 */
(function () {
  "use strict";

  var plan = window.__sdkPlan || {};
  var registrations = 0;
  var sdk = (window.__sdk = {
    calls: [],
    inits: [],
    devices: [],
    published: [],
    unpublished: [],
    left: false,
    admit: function () {},
    end: function () {},
    remoteCamera: function () {},
    remoteAgain: function () {},
    recording: function () {},
    reconnection: function () {},
    remoteShare: function () {},
    stopLocalShare: function () {},
    rights: function () {},
    caption: function () {},
    captioning: false,
    captionLanguage: "",
    releasePublish: function () {},
  });
  var mediaTries = 0;
  var authTries = 0;

  function notAuthorised() {
    return Promise.reject(Object.assign(new Error("not authorised"), { statusCode: 401 }));
  }

  function Emitter() {
    this.handlers = {};
  }
  Emitter.prototype.on = function (name, handler) {
    (this.handlers[name] = this.handlers[name] || []).push(handler);
  };
  Emitter.prototype.once = function (name, handler) {
    var self = this;
    this.on(name, function wrapper(value) {
      self.handlers[name] = self.handlers[name].filter(function (h) {
        return h !== wrapper;
      });
      handler(value);
    });
  };
  Emitter.prototype.emit = function (name, value) {
    (this.handlers[name] || []).slice().forEach(function (handler) {
      handler(value);
    });
  };

  function note(name) {
    sdk.calls.push(name);
  }

  // A stream the way the SDK hands it out: the picture or the sound in `outputStream`.
  function local(kind, options) {
    var constraints = {};
    var wanted = options && options.deviceId ? { deviceId: { exact: options.deviceId } } : true;
    constraints[kind === "camera" ? "video" : "audio"] = wanted;
    sdk.devices.push({ kind: kind, deviceId: (options && options.deviceId) || "" });
    if (options && (plan.deviceFails || []).indexOf(options.deviceId) !== -1) {
      return Promise.reject(Object.assign(new Error("device"), { name: "OverconstrainedError" }));
    }
    return navigator.mediaDevices.getUserMedia(constraints).then(function (stream) {
      return {
        outputStream: stream,
        userMuted: false,
        setUserMuted: function (muted) {
          this.userMuted = muted;
          stream.getTracks().forEach(function (track) {
            track.enabled = !muted;
          });
        },
        stop: function () {
          stream.getTracks().forEach(function (track) {
            track.stop();
          });
        },
      };
    });
  }

  function remoteStreams(meeting) {
    var canvas = document.createElement("canvas");
    canvas.width = 320;
    canvas.height = 180;
    var context = canvas.getContext("2d");
    var step = 0;
    window.setInterval(function () {
      step += 7;
      context.fillStyle = "hsl(" + (step % 360) + " 50% 35%)";
      context.fillRect(0, 0, 320, 180);
    }, 100);
    var audio = new AudioContext();
    var picture = canvas.captureStream(10);
    var track = picture.getVideoTracks()[0];
    // The stand-in keeps the page's mute and unmute listeners itself and calls them, as an engine
    // does for a real change: Firefox does not hand a made-up event on a track to its listeners.
    var heard = { mute: [], unmute: [] };
    var listen = track.addEventListener.bind(track);
    track.addEventListener = function (type, listener, options) {
      if (heard[type]) heard[type].push(listener);
      else listen(type, listener, options);
    };
    sdk.remoteCamera = function (on) {
      Object.defineProperty(track, "muted", {
        configurable: true,
        get: function () {
          return !on;
        },
      });
      var type = on ? "unmute" : "mute";
      heard[type].forEach(function (listener) {
        listener.call(track, new Event(type));
      });
    };
    var sound = audio.createMediaStreamDestination().stream;
    meeting.emit("media:ready", { type: "remoteVideo", stream: picture });
    meeting.emit("media:ready", { type: "remoteAudio", stream: sound });
    sdk.remoteAgain = function () {
      meeting.emit("media:ready", { type: "remoteAudio", stream: sound });
    };
  }

  function screenStream() {
    var canvas = document.createElement("canvas");
    canvas.width = 320;
    canvas.height = 180;
    var context = canvas.getContext("2d");
    context.fillStyle = "#335577";
    context.fillRect(0, 0, 320, 180);
    window.setInterval(function () {
      context.fillRect(0, 0, 320, 180);
    }, 100);
    return canvas.captureStream(10);
  }

  function Meeting(meetings) {
    Emitter.call(this);
    var self = this;
    this.isUserUnadmitted = false;
    this.joined = false;
    this.selfId = "self-member";
    this.rights = { share: plan.canShare !== false, captions: Boolean(plan.captions) };
    this.inMeetingActions = {
      get: function () {
        return { canShareDesktop: self.rights.share, canRealtimeCloseCaption: self.rights.captions };
      },
    };
    sdk.rights = function (share, captions) {
      self.rights = { share: share, captions: captions };
      self.emit("meeting:actionsUpdate", {});
    };
    sdk.remoteShare = function (on) {
      if (on) self.emit("media:ready", { type: "remoteShare", stream: screenStream() });
      self.emit(on ? "meeting:startedSharingRemote" : "meeting:stoppedSharingRemote", {});
    };
    sdk.stopLocalShare = function () {
      self.emit("meeting:stoppedSharingLocal", {});
    };
    sdk.caption = function (spec) {
      var speaker = function (own) {
        return own ? { speakerId: self.selfId, name: "Platform Self Name" } : { speakerId: "other-member", name: "Platform Person Name" };
      };
      var make = function (final) {
        return function (c) {
          return { id: c.id, text: c.text, isFinal: final, timestamp: 1, speaker: speaker(c.own) };
        };
      };
      self.emit("meeting:caption-received", {
        captions: (spec.finals || []).map(make(true)),
        interimCaptions: { "csi-1": (spec.interim || []).map(make(false)) },
      });
    };
    sdk.admit = function () {
      self.isUserUnadmitted = false;
      self.emit("meeting:self:guestAdmitted");
    };
    sdk.end = function () {
      meetings.emit("meeting:removed", {});
    };
    sdk.recording = function (on, payload) {
      self.emit(on ? "meeting:recording:started" : "meeting:recording:stopped", payload);
    };
    sdk.reconnection = function (step, payload) {
      var names = { start: "Starts", success: "Success", fail: "Failure" };
      self.emit("meeting:reconnection" + names[step], payload);
    };
  }
  Meeting.prototype = Object.create(Emitter.prototype);
  Meeting.prototype.join = function () {
    note("join");
    if (plan.authFailAt === "join" && (authTries += 1) === 1) return notAuthorised();
    var self = this;
    return new Promise(function (resolve) {
      window.setTimeout(resolve, plan.joinDelay || 0);
    }).then(function () {
      self.joined = true;
      self.isUserUnadmitted = Boolean(plan.lobby);
    });
  };
  Meeting.prototype.addMedia = function (options) {
    note("addMedia");
    var kinds = Object.keys((options && options.localStreams) || {});
    sdk.added = kinds;
    mediaTries += 1;
    if (mediaTries <= (plan.mediaFailures || 0)) return Promise.reject(new Error("media"));
    if (plan.remote !== false) remoteStreams(this);
    return Promise.resolve();
  };
  Meeting.prototype.publishStreams = function (streams) {
    note("publishStreams");
    if (plan.publishFails || (streams.screenShare && plan.shareSendFails)) return Promise.reject(new Error("refused"));
    if (streams.screenShare && plan.holdPublish) {
      // Under way until the test lets it land: a press or an end while a share is being sent.
      return new Promise(function (resolve) {
        sdk.releasePublish = function () {
          sdk.published = sdk.published.concat(Object.keys(streams));
          resolve();
        };
      });
    }
    sdk.published = sdk.published.concat(Object.keys(streams));
    return Promise.resolve();
  };
  Meeting.prototype.unpublishStreams = function (streams) {
    note("unpublishStreams");
    if (plan.unpublishFails) return Promise.reject(new Error("refused"));
    if (plan.hangUnpublish) return new Promise(function () {});
    return new Promise(function (resolve) {
      window.setTimeout(function () {
        sdk.unpublished = (sdk.unpublished || []).concat(streams.length);
        resolve();
      }, plan.slowUnpublish || 0);
    });
  };
  Meeting.prototype.isTranscriptionSupported = function () {
    return this.rights.captions;
  };
  Meeting.prototype.updateLLMConnection = function () {
    note("updateLLMConnection");
    return Promise.resolve();
  };
  Meeting.prototype.startTranscription = function () {
    note("startTranscription");
    if (plan.captionsFail) return Promise.reject(new Error("refused"));
    var self = this;
    return Promise.resolve().then(function () {
      sdk.captioning = true;
      window.setTimeout(function () {
        self.emit("meeting:receiveTranscription:started", {});
      }, 0);
    });
  };
  Meeting.prototype.stopTranscription = function () {
    note("stopTranscription");
    sdk.captioning = false;
  };
  Meeting.prototype.setCaptionLanguage = function (language) {
    note("setCaptionLanguage");
    sdk.captionLanguage = language;
    return Promise.resolve();
  };
  Meeting.prototype.leave = function () {
    note("leave");
    sdk.left = true;
    return new Promise(function (resolve) {
      window.setTimeout(resolve, plan.slowLeave || 0);
    });
  };

  function Meetings() {
    Emitter.call(this);
    this.registered = false;
    this.mediaHelpers = {
      createMicrophoneStream: function (options) {
        note("createMicrophoneStream");
        return local("microphone", options);
      },
      createCameraStream: function (options) {
        note("createCameraStream");
        return local("camera", options);
      },
      // The browser's own picker gives the screen (the test stubs it); the stream ends when its track does.
      createDisplayStream: function () {
        note("createDisplayStream");
        return navigator.mediaDevices.getDisplayMedia({ video: true }).then(function (stream) {
          return {
            outputStream: stream,
            stop: function () {
              stream.getTracks().forEach(function (track) {
                track.stop();
              });
            },
            on: function (name, handler) {
              if (name === "stream-ended") stream.getVideoTracks()[0].addEventListener("ended", handler);
            },
          };
        });
      },
    };
  }
  Meetings.prototype = Object.create(Emitter.prototype);
  Meetings.prototype.register = function () {
    note("register");
    registrations += 1;
    if (registrations <= (plan.authFailures || 0)) {
      return Promise.reject(Object.assign(new Error("not authorised"), { statusCode: 401 }));
    }
    if (plan.always || registrations <= (plan.failures || 0)) {
      return Promise.reject(new Error("refused"));
    }
    if (registrations <= (plan.failures || 0) + (plan.hang || 0)) return new Promise(function () {});
    var self = this;
    var wait = registrations === 1 && plan.late ? plan.late : plan.delay || 0;
    return new Promise(function (resolve) {
      window.setTimeout(function () {
        self.registered = true;
        resolve();
      }, wait);
    });
  };
  Meetings.prototype.unregister = function () {
    note("unregister");
    this.registered = false;
    return Promise.resolve();
  };
  Meetings.prototype.create = function (link) {
    note("create");
    if (plan.authFailAt === "create" && (authTries += 1) === 1) return notAuthorised();
    sdk.link = link;
    return Promise.resolve(new Meeting(this));
  };

  window.Webex = {
    init: function (options) {
      note("init");
      var credentials = (options && options.credentials) || {};
      sdk.inits.push({
        token: credentials.access_token,
        autoUploadLogs: options.config.meetings.autoUploadLogs,
        automaticLLM: options.config.meetings.enableAutomaticLLM,
        ephemeral: options.config.device.ephemeral,
      });
      var client = new Emitter();
      client.ready = true;
      client.meetings = new Meetings();
      return client;
    },
  };
})();
